#!/usr/bin/env python3
"""Inactive synthetic author cases. No active curriculum/ledger writes."""
import json
from pathlib import Path

B = Path(__file__).resolve().parent
IDS = json.loads((B / 'scope20.json').read_text())
GOALS = {r['goal']['id']: r['goal'] for r in json.loads((B / 'whole20.current-native-goals.requires.parents.snapshot.json').read_text())}
CASES = []

def pair(de, en):
    return {'de': de, 'en': en}

def add(i, variant, title, material, task, answer, criteria, transfer, transfer_answer):
    assert len(criteria) == 4
    CASES.append({
        'caseId': f'q3-{i:02d}-{variant}', 'goalId': IDS[i-1], 'title': title,
        'wholeCurrentGoal': GOALS[IDS[i-1]],
        'material': material, 'task': task, 'modelResponse': answer,
        'scoring': {'maximumPoints': 10, 'criteria': [
            {'id': f'c{n}', 'points': 2, 'criterion': c} for n, c in enumerate(criteria, 1)
        ] + [{'id': 'fresh-transfer', 'points': 2, 'criterion': transfer_answer}],
        'rule': pair('Punkte ausschließlich für ausdrücklich gezeigte Fachleistung. Volle Punkte pro Kriterium nur bei Begründung und korrekter Darstellung; ein richtiger Fachbegriff allein genügt nicht. Modellantworten sind Autorenbeispiele, keine Lernendenleistung.',
                     'Award points only for explicitly demonstrated scientific performance. Full credit per criterion requires reasoning and correct representation; a correct term alone is insufficient. Model responses are author examples, not learner performance.')},
        'freshTransfer': {'task': transfer, 'modelResponse': transfer_answer,
                          'independentAdministration': True, 'releaseModelOnlyAfterSubmission': True},
        'evidence': {'level': 'E1', 'maximumClaimScope': 'G1', 'kind': 'synthetic-author-witness',
                     'humanTrial': False, 'performedExperiment': False, 'actualLearnerPerformance': False}
    })

# 1: dynamic equilibrium: simultaneous species, equal nonzero rates, two levels.
add(1,'a',pair('Geschlossenes Modell mit markierten Teilchen','Closed model with labelled particles'),
    pair('Modell A ⇌ B, geschlossen, konstante Temperatur. Nach 5 und 10 min: jeweils 60 A- und 40 B-Teilchen. Im dazwischenliegenden Zeitfenster werden 12 Übergänge A→B und 12 B→A registriert. Ein validierter artspezifischer Nachweis zeigt A und B in derselben Probe. Alle Zahlen sind synthetisch.',
         'Model A ⇌ B, closed, constant temperature. At 5 and 10 min there are 60 A and 40 B particles. Between readings, 12 A→B and 12 B→A transitions are recorded. A validated species-specific assay identifies A and B in the same sample. All numbers are synthetic.'),
    pair('Charakterisiere das Gleichgewicht mit einem Stoff- und einem Teilchenmodell. Begründe gleichzeitiges Vorliegen und unterscheide Nettoänderung, Hin- und Rückreaktion. Widerlege „60:40 bedeutet kein Gleichgewicht“.',
         'Characterize equilibrium with substance and particle models. Explain coexistence and distinguish net change, forward and reverse reaction. Refute “60:40 means no equilibrium”.'),
    pair('Auf Stoffebene bleiben Zusammensetzung und makroskopische Konzentrationen konstant; der Nachweis belegt beide Stoffarten. Auf Teilchenebene laufen beide Richtungen weiter, mit gleicher, nicht nuller Rate. Die Nettoänderung ist null. Gleichgewicht fordert keine gleichen Mengen; 60:40 ist möglich. Das Modell ist kein experimenteller Nachweis realer Reaktionsraten.',
         'At substance level composition and macroscopic concentrations remain constant; the assay identifies both species. At particle level both directions continue at equal nonzero rates. Net change is zero. Equilibrium does not require equal amounts; 60:40 is possible. The model is not an experimental measurement of actual reaction rates.'),
    [pair('Beide Stoffarten mit Nachweis, nicht nur konstantem Gesamtsignal belegen.','Establish both species using the assay, not merely a constant total signal.'),pair('Konstante Stoffebene korrekt darstellen.','Represent the constant substance level correctly.'),pair('12 Hin- und 12 Rückübergänge als dynamisch erklären.','Explain the 12 forward and 12 reverse transitions as dynamic.'),pair('Netto null von Stillstand und gleichen Mengen trennen.','Distinguish zero net change from stopped reactions and equal amounts.')],
    pair('Frische Modellprobe: 20 A, 80 B; 7 Übergänge je Richtung. Ist das Gleichgewicht? Was beweist allein eine konstante Farbe?','Fresh model sample: 20 A, 80 B; 7 transitions in each direction. Is it equilibrium? What does constant colour alone prove?'),
    pair('Ja im angegebenen geschlossenen Modell: gleiche nicht nuller Raten. Konstante Farbe allein belegt weder beide Arten noch die laufenden Teilchenübergänge.','Yes in the stated closed model: equal nonzero rates. Constant colour alone establishes neither both species nor continuing particle transitions.'))
add(1,'b',pair('Zwei Startzusammensetzungen','Two starting compositions'),
    pair('Zwei geschlossene A⇌B-Modellgefäße bei gleicher Temperatur enthalten je 100 Teilchen. X beginnt mit 100 A, Y mit 100 B. Beide erreichen 25 A/75 B. Im Endzustand zeigt die Verfolgung einzelner Teilchen je 9 Hin- und Rückübergänge pro Sekunde, und zwei getrennte Nachweise sind positiv.',
         'Two closed A⇌B model vessels at the same temperature contain 100 particles each. X starts with 100 A, Y with 100 B. Both reach 25 A/75 B. At the endpoint particle tracking records 9 forward and 9 reverse transitions per second, and two separate assays are positive.'),
    pair('Nutze beide Modellebenen und beide Nachweise, um den gemeinsamen Endzustand zu charakterisieren. Erkläre, warum eine konstante Zusammensetzung nicht das Ende der Reaktionen bedeutet.',
         'Use both model levels and both assays to characterize the shared endpoint. Explain why constant composition does not mean reactions have ended.'),
    pair('Beide Nachweise belegen Edukt und Produkt gleichzeitig. Die Gefäße erreichen dieselbe makroskopische Zusammensetzung trotz verschiedener Startzustände. Weiterlaufende Teilchenübergänge mit gleichen Raten erhalten diese Zusammensetzung; einzelne Teilchen wechseln ihre Art. Der Vergleich stützt das dynamische Modell unter den angegebenen Bedingungen, beweist aber nicht jede reale Reaktion.',
         'Both assays establish reactant and product simultaneously. The vessels reach the same macroscopic composition despite different starts. Continuing particle transitions at equal rates maintain that composition; individual particles change species. The comparison supports the dynamic model under the stated conditions, not every actual reaction.'),
    [pair('Gemeinsamen Stoffzustand mit verschiedenen Startzuständen vergleichen.','Compare the common substance state with different starts.'),pair('Simultane Artenpräsenz belegen.','Establish simultaneous presence of both species.'),pair('Gleiche nicht nuller Teilchenraten begründen.','Explain equal nonzero particle rates.'),pair('Makroskopische Konstanz und mikroskopischen Umsatz unterscheiden.','Distinguish macroscopic constancy and microscopic turnover.')],
    pair('Bei einem offenen Gefäß wird B laufend entfernt; A und B bleiben scheinbar konstant, Hinrate 9 und Rückrate 3. Gleicher Befund?','In an open vessel B is continually removed; A and B appear constant, with forward rate 9 and reverse rate 3. Is this the same finding?'),
    pair('Nein: ein stationärer offener Zustand mit Zu-/Abfluss kann konstante Werte zeigen. Ungleiche Reaktionsraten erfüllen hier nicht das geschlossene chemische Gleichgewicht.','No: a steady open state with flows can show constant values. Unequal reaction rates do not satisfy closed chemical equilibrium here.'))

# 2: simplified homogeneous equilibrium; powers and temperature-specific K.
add(2,'a',pair('Homogenes Estermodell','Homogeneous ester model'),
    pair('Idealisierte homogene Lösung: Säure + Alkohol ⇌ Ester + Wasser, stöchiometrisch 1:1:1:1. Gleichgewicht bei T: c(Säure)=c(Alkohol)=0,20 mol/L, c(Ester)=c(Wasser)=0,40 mol/L; Aktivitäten werden durch c/c° mit c°=1 mol/L angenähert.',
         'Idealized homogeneous solution: acid + alcohol ⇌ ester + water, stoichiometry 1:1:1:1. At equilibrium at T: c(acid)=c(alcohol)=0.20 mol/L and c(ester)=c(water)=0.40 mol/L; activities are approximated by c/c° with c°=1 mol/L.'),
    pair('Formuliere das MWG, berechne K und interpretiere die Lage. Berechne den Quotienten unmittelbar nach Verdopplung der Säurekonzentration. Unterscheide ihn von K.',
         'Write the mass action expression, calculate K and interpret equilibrium position. Calculate the quotient immediately after doubling acid concentration. Distinguish it from K.'),
    pair('K=(cE/c°)(cW/c°)/[(cS/c°)(cA/c°)]=0,40²/0,20²=4. Produkte sind im Verhältnis des MWG begünstigt, nicht quantitativ vollständig gebildet. Unmittelbar nach Säurezugabe ist Q=0,16/(0,40·0,20)=2<K; der Nettoverlauf geht nach rechts, bis Q wieder 4 ist. Bei unverändertem T bleibt K=4.',
         'K=(cE/c°)(cW/c°)/[(cS/c°)(cA/c°)]=0.40²/0.20²=4. Products are favoured in the mass action ratio, not formed completely. Immediately after acid addition Q=0.16/(0.40·0.20)=2<K; net reaction proceeds right until Q returns to 4. At unchanged T, K stays 4.'),
    [pair('Alle vier Stoffe mit richtigen Potenzen einbeziehen.','Include all four species with correct powers.'),pair('K=4 aus Gleichgewichtsdaten berechnen.','Calculate K=4 from equilibrium data.'),pair('Zahlenwert ohne vollständigen Umsatz oder Geschwindigkeitsaussage deuten.','Interpret the number without claiming complete conversion or a rate.'),pair('Q=2 und konstantes K=4 unterscheiden.','Distinguish Q=2 and constant K=4.')],
    pair('Frisches homogenes 1:1:1:1-System mit cP=cQ=0,10 und cR=cS=0,50 mol/L: bestimme K für P+Q⇌R+S und für die umgekehrte Gleichung.','Fresh homogeneous 1:1:1:1 system with cP=cQ=0.10 and cR=cS=0.50 mol/L: determine K for P+Q⇌R+S and its reverse.'),
    pair('K=25; für die Rückgleichung 1/25=0,04. Die Interpretation gehört immer zur angegebenen Reaktionsgleichung.','K=25; for the reverse equation 1/25=0.04. Interpretation always belongs to the specified reaction equation.'))
add(2,'b',pair('Gleichgewichtskonzentration aus Stoffbilanz','Equilibrium concentration from balance'),
    pair('Homogenes Modell A+B⇌C+D bei T, K=9. Anfang: je 1,00 mol/L A und B, kein C oder D; gleichbleibendes Volumen. Zulässiger Umsatz x liegt zwischen 0 und 1,00 mol/L.',
         'Homogeneous model A+B⇌C+D at T, K=9. Initially A and B are each 1.00 mol/L, with no C or D; constant volume. Allowed conversion x lies between 0 and 1.00 mol/L.'),
    pair('Berechne alle Gleichgewichtskonzentrationen mit MWG und Bilanz. Prüfe deine Lösung durch Einsetzen und interpretiere K. Eine andere Probe bei gleichem T hat Q=18; deute sie.',
         'Calculate all equilibrium concentrations using mass action and balance. Check by substitution and interpret K. Another sample at the same T has Q=18; interpret it.'),
    pair('cA=cB=1−x, cC=cD=x. 9=x²/(1−x)²; für nichtnegative Konzentrationen x/(1−x)=3, also x=0,75 mol/L. A/B je 0,25, C/D je 0,75; 0,75²/0,25²=9. Das produktbegünstigte Gleichgewicht enthält trotzdem A/B. Q=18>K bedeutet Nettoverlauf nach links; es ist kein neues K.',
         'cA=cB=1−x and cC=cD=x. 9=x²/(1−x)²; for nonnegative concentrations x/(1−x)=3, so x=0.75 mol/L. A/B are each 0.25 and C/D each 0.75; 0.75²/0.25²=9. Product-favoured equilibrium still contains A/B. Q=18>K means net reaction left; it is not a new K.'),
    [pair('Bilanz und zulässigen Bereich angeben.','State balance and allowed range.'),pair('MWG korrekt lösen und alle Konzentrationen nennen.','Solve mass action correctly and state all concentrations.'),pair('Einsetzprobe und begrenzte K-Interpretation leisten.','Check by substitution and give bounded interpretation of K.'),pair('Q>K als Rückverschiebung bei unverändertem K deuten.','Interpret Q>K as reverse shift at unchanged K.')],
    pair('Frisch: Start je 0,60 mol/L, K=4, gleiche Reaktion.','Fresh: initial concentrations each 0.60 mol/L, K=4, same reaction.'),
    pair('x/(0,60−x)=2, x=0,40; Edukte je0,20 und Produkte je0,40 mol/L. K bleibt trotz anderer Startmengen4.','x/(0.60−x)=2, x=0.40; reactants each0.20 and products each0.40 mol/L. K remains4 despite different initial amounts.'))

