    [pair('Endotherme Temperaturreaktion korrekt deuten.','Interpret endothermic temperature response correctly.'),pair('Umsatzverschiebung von absoluter Konzentration bei Kompression trennen.','Distinguish conversion shift from absolute concentration under compression.'),pair('Stoffzugabe und gelöstes Alltagsgas erklären.','Explain added species and dissolved everyday gas.'),pair('Kinetische Schlussfolgerungen begrenzen.','Bound kinetic conclusions.')],
    pair('Frisch: Produktgas wird bei konstantem T und Volumen teilweise entfernt. Was geschieht mit Q und Nettoverlauf?','Fresh: product gas is partly removed at constant T and volume. What happens to Q and net reaction?'),
